package net.chickensell;

import net.milkbowl.vault.economy.Economy;
import org.bukkit.*;import org.bukkit.command.*;import org.bukkit.configuration.file.YamlConfiguration;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.inventory.*;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.plugin.*;import org.bukkit.plugin.java.JavaPlugin;import java.io.*;import java.util.*;

public final class ChickenSell extends JavaPlugin implements Listener{
 private static final int SELL_AREA_END=45,BLOCKS_SLOT=46,MINING_SLOT=47,SELL_BUTTON_SLOT=49;
 private static final double[] LEVEL_TARGETS={25000d,150000d,500000d,1000000d,5000000d,25000000d,250000000d,550000000d,850000000d,1000000000d,2000000000d,4000000000d,8000000000d,10000000000d,20000000000d,40000000000d,80000000000d,160000000000d,320000000000d,640000000000d};
 private static final int[] LEVEL_SLOTS={10,19,28,37,38,39,30,21,12,13,14,23,32,41,42,43,34,25,16,7};
 private final Map<Material,Double> prices=new LinkedHashMap<>();private final Map<Material,Category> categories=new HashMap<>();private Economy economy;private File dataFile;private YamlConfiguration data;
 @Override public void onEnable(){if(!setupEconomy()){getServer().getPluginManager().disablePlugin(this);return;}loadPrices();loadData();Bukkit.getPluginManager().registerEvents(this,this);getLogger().info("ChickenSell 1.5.0 enabled");}
 private boolean setupEconomy(){RegisteredServiceProvider<Economy> r=getServer().getServicesManager().getRegistration(Economy.class);if(r==null)return false;economy=r.getProvider();return economy!=null;}
 private void add(Material m,double p,Category c){prices.put(m,p);categories.put(m,c);}private void mining(Material m,double p){add(m,p,Category.MINING);}
 private void loadPrices(){for(Material m:Material.values())if(m.isBlock()&&!m.isAir()&&m.isItem())add(m,defaultBlockPrice(m),Category.BLOCKS);
  mining(Material.COAL,18);mining(Material.COAL_ORE,22);mining(Material.DEEPSLATE_COAL_ORE,25);mining(Material.COAL_BLOCK,160);mining(Material.IRON_ORE,38);mining(Material.DEEPSLATE_IRON_ORE,42);mining(Material.RAW_IRON,35);mining(Material.IRON_INGOT,75);mining(Material.IRON_NUGGET,9);mining(Material.IRON_BLOCK,675);mining(Material.COPPER_ORE,28);mining(Material.DEEPSLATE_COPPER_ORE,32);mining(Material.RAW_COPPER,24);mining(Material.COPPER_INGOT,48);mining(Material.COPPER_BLOCK,430);mining(Material.GOLD_ORE,70);mining(Material.DEEPSLATE_GOLD_ORE,78);mining(Material.NETHER_GOLD_ORE,65);mining(Material.RAW_GOLD,68);mining(Material.GOLD_INGOT,110);mining(Material.GOLD_NUGGET,13);mining(Material.GOLD_BLOCK,990);mining(Material.REDSTONE_ORE,32);mining(Material.DEEPSLATE_REDSTONE_ORE,36);mining(Material.REDSTONE,16);mining(Material.REDSTONE_BLOCK,144);mining(Material.LAPIS_ORE,40);mining(Material.DEEPSLATE_LAPIS_ORE,45);mining(Material.LAPIS_LAZULI,22);mining(Material.LAPIS_BLOCK,198);mining(Material.DIAMOND_ORE,425);mining(Material.DEEPSLATE_DIAMOND_ORE,475);mining(Material.DIAMOND,500);mining(Material.DIAMOND_BLOCK,4500);mining(Material.EMERALD_ORE,300);mining(Material.DEEPSLATE_EMERALD_ORE,340);mining(Material.EMERALD,350);mining(Material.EMERALD_BLOCK,3150);mining(Material.NETHER_QUARTZ_ORE,28);mining(Material.QUARTZ,20);mining(Material.AMETHYST_SHARD,32);mining(Material.AMETHYST_BLOCK,120);mining(Material.BUDDING_AMETHYST,180);mining(Material.SMALL_AMETHYST_BUD,35);mining(Material.MEDIUM_AMETHYST_BUD,55);mining(Material.LARGE_AMETHYST_BUD,80);mining(Material.AMETHYST_CLUSTER,110);mining(Material.ANCIENT_DEBRIS,750);mining(Material.NETHERITE_SCRAP,850);mining(Material.NETHERITE_INGOT,3500);mining(Material.NETHERITE_BLOCK,31500);mining(Material.ECHO_SHARD,400);
  add(Material.WHEAT,10,Category.OTHER);add(Material.CARROT,8,Category.OTHER);add(Material.POTATO,8,Category.OTHER);
 }
 private double defaultBlockPrice(Material m){String n=m.name();if(n.contains("DIAMOND"))return 450;if(n.contains("EMERALD"))return 325;if(n.contains("NETHERITE"))return 900;if(n.contains("GOLD"))return 95;if(n.contains("IRON"))return 65;if(n.contains("COPPER"))return 30;if(n.contains("OBSIDIAN"))return 35;if(n.contains("QUARTZ"))return 30;if(n.endsWith("_LOG")||n.endsWith("_WOOD")||n.endsWith("_STEM")||n.endsWith("_HYPHAE"))return 12;if(n.contains("GLASS"))return 8;if(n.contains("TERRACOTTA")||n.contains("CONCRETE"))return 10;if(n.contains("WOOL"))return 9;if(n.contains("PLANKS"))return 8;if(n.contains("SAND")||n.contains("GRAVEL"))return 5;if(n.contains("DIRT")||n.contains("MUD"))return 3;return 7;}
 private void loadData(){if(!getDataFolder().exists())getDataFolder().mkdirs();dataFile=new File(getDataFolder(),"playerdata.yml");data=YamlConfiguration.loadConfiguration(dataFile);}private void saveData(){try{data.save(dataFile);}catch(IOException e){getLogger().severe(e.getMessage());}}
 @Override public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!c.getName().equalsIgnoreCase("sell"))return false;if(s instanceof Player p)openSellMenu(p);return true;}
 private void openSellMenu(Player p){Inventory i=Bukkit.createInventory(new MenuHolder(MenuType.SELL,p.getUniqueId(),0,Category.OTHER),54,"§8SATIŞ MENÜSÜ");i.setItem(BLOCKS_SLOT,button(Material.GRASS_BLOCK,"§a§lBLOKLAR",List.of("§7Blok kategorisini aç.","","§eTıkla!")));i.setItem(MINING_SLOT,button(Material.DIAMOND,"§b§lMADEN",List.of("§7Maden kategorisini aç.","","§eTıkla!")));i.setItem(SELL_BUTTON_SLOT,button(Material.EMERALD,"§a§lSAT",List.of("§7Üstteki 45 slota eşyalarını koy.","","§eSatmak için tıkla!")));p.openInventory(i);}
 private void openCategory(Player p,Category cat){Inventory i=Bukkit.createInventory(new MenuHolder(MenuType.CATEGORY,p.getUniqueId(),0,cat),54,"§8"+cat.title+" KATEGORİSİ");fill(i,Material.GRAY_STAINED_GLASS_PANE," ");double earned=getEarned(p,cat);int completed=getCompletedLevels(earned),current=Math.min(completed+1,20);for(int x=0;x<20;x++){int level=x+1;Material pane=level<=completed?Material.LIGHT_BLUE_STAINED_GLASS_PANE:(level==current&&completed<20?Material.YELLOW_STAINED_GLASS_PANE:Material.RED_STAINED_GLASS_PANE);double start=x==0?0:LEVEL_TARGETS[x-1],target=LEVEL_TARGETS[x];String status=level<=completed?"§bTAMAMLANDI":(level==current&&completed<20?"§eİLERLİYOR":"§cKİLİTLİ");i.setItem(LEVEL_SLOTS[x],button(pane,"§f§lLEVEL "+level,List.of(status,"§7Hedef: §6$"+money(target),"§7Aralık: §f$"+money(start)+" §7→ §f$"+money(target),"§7Bitince: §a"+String.format(Locale.US,"%.1fx",1.0+level*.1))));}i.setItem(4,progressBook(p,cat));i.setItem(1,button(cat.icon,"§e§l"+cat.title+" EŞYALARI",List.of("§7Eşyaları ve fiyatlarını gör.","","§eTıkla!")));i.setItem(53,button(Material.ARROW,"§eGeri",List.of("§7Satış menüsüne dön.")));p.openInventory(i);}
 private void openItems(Player p,Category cat,int page){List<Material> items=new ArrayList<>();for(Material m:prices.keySet())if(categories.get(m)==cat)items.add(m);items.sort(Comparator.comparing(Enum::name));int per=45,max=Math.max(0,(items.size()-1)/per);page=Math.max(0,Math.min(page,max));Inventory i=Bukkit.createInventory(new MenuHolder(MenuType.ITEMS,p.getUniqueId(),page,cat),54,"§8"+cat.title+" §7• Sayfa "+(page+1)+"/"+(max+1));double mult=getMultiplier(p,cat);int start=page*per;for(int s=0;s<per&&start+s<items.size();s++){Material m=items.get(start+s);double base=prices.get(m);i.setItem(s,button(m,"§f"+pretty(m),List.of("§7Normal fiyat: §e$"+money(base),"§7Çarpanın: §a"+String.format(Locale.US,"%.1fx",mult),"§7Satış fiyatın: §6$"+money(base*mult))));}i.setItem(45,button(Material.BOOK,"§eİlerleme",List.of("§7Level ekranına dön.")));if(page>0)i.setItem(48,button(Material.ARROW,"§eÖnceki Sayfa",List.of()));if(page<max)i.setItem(50,button(Material.ARROW,"§eSonraki Sayfa",List.of()));i.setItem(53,button(Material.BARRIER,"§cGeri",List.of()));p.openInventory(i);}
 private ItemStack progressBook(Player p,Category cat){double e=getEarned(p,cat);int completed=getCompletedLevels(e);double mult=getMultiplier(p,cat);if(completed>=20)return button(Material.BOOK,"§e§l"+cat.title+" İLERLEMESİ",List.of("§7Tamamlanan: §f20§7/20","§7Çarpan: §a3.0x","§7Toplam: §6$"+money(e),"","§bTÜM LEVELLAR TAMAMLANDI!"));double target=LEVEL_TARGETS[completed];return button(Material.BOOK,"§e§l"+cat.title+" İLERLEMESİ",List.of("§7Şu anki level: §f"+(completed+1)+"§7/20","§7Çarpan: §a"+String.format(Locale.US,"%.1fx",mult),"§7Toplam: §6$"+money(e),"","§7İlerleme: §e$"+money(e)+" §7/ §e$"+money(target),"§7Hedef: §6$"+money(target)));}
 private void fill(Inventory i,Material m,String n){for(int s=0;s<i.getSize();s++)i.setItem(s,button(m,n,List.of()));}private ItemStack button(Material m,String n,List<String> lore){ItemStack it=new ItemStack(m);ItemMeta meta=it.getItemMeta();meta.setDisplayName(n);meta.setLore(lore);it.setItemMeta(meta);return it;}
 @EventHandler public void onInventoryClick(InventoryClickEvent e){if(!(e.getInventory().getHolder() instanceof MenuHolder h)||!(e.getWhoClicked() instanceof Player p))return;if(!h.owner.equals(p.getUniqueId())){e.setCancelled(true);return;}int s=e.getRawSlot();if(h.type==MenuType.SELL){if(s>=SELL_AREA_END&&s<54){e.setCancelled(true);if(s==BLOCKS_SLOT||s==MINING_SLOT){returnSellItems(p,e.getInventory());openCategory(p,s==BLOCKS_SLOT?Category.BLOCKS:Category.MINING);}else if(s==SELL_BUTTON_SLOT)sellItems(p,e.getInventory());}return;}e.setCancelled(true);if(h.type==MenuType.CATEGORY){if(s==1)openItems(p,h.cat,0);else if(s==53)openSellMenu(p);}else if(h.type==MenuType.ITEMS){if(s==45||s==53)openCategory(p,h.cat);else if(s==48&&h.page>0)openItems(p,h.cat,h.page-1);else if(s==50)openItems(p,h.cat,h.page+1);}}
 private void sellItems(Player p,Inventory i){double total=0;Map<Category,Double> earned=new EnumMap<>(Category.class);int amount=0;for(int s=0;s<SELL_AREA_END;s++){ItemStack it=i.getItem(s);if(it==null||it.getType().isAir())continue;Double price=prices.get(it.getType());if(price==null)continue;Category c=categories.getOrDefault(it.getType(),Category.OTHER);double line=price*it.getAmount()*getMultiplier(p,c);total+=line;if(c!=Category.OTHER)earned.merge(c,line,Double::sum);amount+=it.getAmount();i.setItem(s,null);}if(amount==0){p.sendMessage("§cSatılabilir bir eşya koymadın.");return;}economy.depositPlayer(p,total);earned.forEach((c,v)->addEarned(p,c,v));p.sendMessage("§a"+amount+" eşya sattın ve §e$"+money(total)+" §akazandın!");p.closeInventory();}
 private void addEarned(Player p,Category c,double a){String path=p.getUniqueId()+"."+c.key+".earned";double before=data.getDouble(path,0),after=before+a;int old=getCompletedLevels(before);data.set(path,after);saveData();int now=getCompletedLevels(after);if(now>old)p.sendMessage("§6§lLEVEL TAMAMLANDI! §e"+c.title+" leveli: §f"+now+" §7• Yeni çarpan: §a"+String.format(Locale.US,"%.1fx",getMultiplierFromEarned(after)));}
 private double getEarned(Player p,Category c){return data.getDouble(p.getUniqueId()+"."+c.key+".earned",0);}private int getCompletedLevels(double e){int n=0;for(double t:LEVEL_TARGETS){if(e>=t)n++;else break;}return n;}private double getMultiplier(Player p,Category c){return c==Category.OTHER?1:getMultiplierFromEarned(getEarned(p,c));}private double getMultiplierFromEarned(double e){return Math.min(3,1+getCompletedLevels(e)*.1);}private String pretty(Material m){String[] a=m.name().toLowerCase(Locale.ROOT).split("_");StringBuilder r=new StringBuilder();for(String x:a){if(!r.isEmpty())r.append(' ');r.append(Character.toUpperCase(x.charAt(0))).append(x.substring(1));}return r.toString();}private String money(double a){return String.format(Locale.US,"%,.2f",a);}
 @EventHandler public void onInventoryClose(InventoryCloseEvent e){if(e.getInventory().getHolder() instanceof MenuHolder h&&h.type==MenuType.SELL&&e.getPlayer() instanceof Player p)returnSellItems(p,e.getInventory());}private void returnSellItems(Player p,Inventory i){for(int s=0;s<SELL_AREA_END;s++){ItemStack it=i.getItem(s);if(it==null||it.getType().isAir())continue;i.setItem(s,null);Map<Integer,ItemStack> left=p.getInventory().addItem(it);left.values().forEach(x->p.getWorld().dropItemNaturally(p.getLocation(),x));}}@Override public void onDisable(){saveData();}
 private enum Category{BLOCKS("blocks","BLOK",Material.GRASS_BLOCK),MINING("mining","MADEN",Material.DIAMOND),OTHER("other","DİĞER",Material.CHEST);final String key,title;final Material icon;Category(String k,String t,Material i){key=k;title=t;icon=i;}}private enum MenuType{SELL,CATEGORY,ITEMS}private static final class MenuHolder implements InventoryHolder{final MenuType type;final UUID owner;final int page;final Category cat;MenuHolder(MenuType t,UUID o,int p,Category c){type=t;owner=o;page=p;cat=c;}@Override public Inventory getInventory(){return null;}}
}
